INSERT INTO expense_prior_control(tenant_id,report_id,round_no,application_id,application_version,financial_version,
    definition_id,definition_version,submitted_at,requires_approval,snapshot_json)
SELECT e.tenant_id,e.id,#{roundNo},a.id,a.version,e.version,d.id,d.version,#{submittedAt},#{requiresApproval},#{stateJson}
FROM expense_report e JOIN approval_application a ON a.tenant_id=e.tenant_id AND a.id=e.application_id
JOIN approval_definition d ON d.tenant_id=a.tenant_id AND d.process_key=a.process_key AND d.version=a.definition_version
WHERE e.tenant_id=#{tenantId} AND e.id=#{reportId} AND a.id=#{applicationId} AND e.version=#{financialVersion} AND a.version=#{applicationVersion} AND e.current_round_no=#{currentRoundNo}
    AND a.status IN ('DRAFT','RETURNED','WITHDRAWN')
    AND (CASE WHEN a.status='DRAFT' THEN a.round_no ELSE a.round_no+1 END)=#{roundNo11}
    AND d.id=#{definitionId} AND d.version=#{definitionVersion} AND d.status='PUBLISHED'
